<file path="inventory.py">
"""Inventory core: items, warehouses, FIFO lots, reorder and overdraft logic.

Partial implementation. Not implemented here: suppliers, sim, transfer,
audit, returns, receive_bulk, report, undo, save/load, turnover, list_price,
and loading data.toml. See the notes in the reply.
"""
from events import EventLog


class DepotError(Exception):
    def __init__(self, code):
        super().__init__(code)
        self.code = code


class Depot:
    def __init__(self, warehouses, capacities, opening_cash, rounding_mode,
                 storage_cents_per_unit_day=2):
        self._warehouses = list(warehouses)
        self._capacities = dict(capacities)
        for wh in self._warehouses:
            if wh not in self._capacities:
                raise ValueError("capacity missing for warehouse %r" % (wh,))
        self._cash = int(opening_cash)
        self._rounding_mode = rounding_mode  # owner's choice (C31); used by list_price later
        self._storage = int(storage_cents_per_unit_day)
        self._items = {}      # sku -> {"unit_cost", "reorder_level", "shelf"}
        self._lots = {}       # (sku, wh) -> list of [day, qty], oldest first (C12)
        self._armed = {}      # (sku, wh) -> bool, REORDER re-arm state (C14)
        self._day = 0
        self._overdrawn = self._cash < 0
        self._events = EventLog()

    # ----- read-only properties -------------------------------------------
    @property
    def cash(self):
        return self._cash

    @property
    def day(self):
        return self._day

    def notifications(self):
        return self._events.notifications()

    # ----- helpers ---------------------------------------------------------
    def _need_sku(self, sku):
        if sku not in self._items:
            raise DepotError("UNKNOWN_SKU")
        return self._items[sku]

    def _need_wh(self, wh):
        if wh not in self._capacities:
            raise DepotError("UNKNOWN_WAREHOUSE")

    @staticmethod
    def _need_qty(qty):
        if isinstance(qty, bool) or not isinstance(qty, int) or qty <= 0:
            raise DepotError("INVALID_QTY")

    def _lots_for(self, sku, wh):
        return self._lots.setdefault((sku, wh), [])

    def stock(self, sku, wh=None):
        """Total stock across warehouses, or in one warehouse (C25)."""
        self._need_sku(sku)
        if wh is None:
            return sum(q for w in self._warehouses for _, q in self._lots.get((sku, w), []))
        self._need_wh(wh)
        return sum(q for _, q in self._lots.get((sku, wh), []))

    def _units_in_wh(self, wh):
        return sum(q for (s, w), lots in self._lots.items() if w == wh for _, q in lots)

    def _update_armed(self, sku, wh):
        """REORDER logic (C14).

        - stock above reorder_level re-arms;
        - stock at or below reorder_level while armed emits REORDER once and disarms.
        Called after shipments only; receipts only re-arm (see receive).
        """
        level = self._items[sku]["reorder_level"]
        st = self.stock(sku, wh)
        if st > level:
            self._armed[(sku, wh)] = True
        elif self._armed.get((sku, wh), True):
            self._events.emit("REORDER", sku, wh)
            self._armed[(sku, wh)] = False

    # ----- catalogue -------------------------------------------------------
    def add_item(self, sku, unit_cost, reorder_level, shelf_life_days=None):
        """C01."""
        if sku in self._items:
            raise DepotError("DUPLICATE_SKU")
        if isinstance(unit_cost, bool) or not isinstance(unit_cost, int) or unit_cost <= 0:
            raise DepotError("INVALID_ARG")
        if isinstance(reorder_level, bool) or not isinstance(reorder_level, int) or reorder_level < 0:
            raise DepotError("INVALID_ARG")
        shelf = shelf_life_days if (shelf_life_days is not None and shelf_life_days >= 1) else None
        self._items[sku] = {"unit_cost": unit_cost, "reorder_level": reorder_level, "shelf": shelf}

    # ----- receiving and shipping -----------------------------------------
    def receive(self, sku, qty, wh):
        """C04, C05, C20."""
        item = self._need_sku(sku)
        self._need_wh(wh)
        self._need_qty(qty)
        if self._cash < 0:                                   # C20
            raise DepotError("OVERDRAWN")
        cost = item["unit_cost"] * qty                       # C05
        if self._cash - cost < 0:
            raise DepotError("INSUFFICIENT_FUNDS")
        if self._units_in_wh(wh) + qty > self._capacities[wh]:  # C04
            raise DepotError("CAPACITY")
        self._cash -= cost
        self._lots_for(sku, wh).append([self._day, qty])     # C12
        # Comment 1: a receipt re-arms only if it lifts stock above the level.
        if self.stock(sku, wh) > item["reorder_level"]:
            self._armed[(sku, wh)] = True

    def ship(self, sku, qty, wh, price):
        """C06, C07, C12, C14."""
        item = self._need_sku(sku)
        self._need_wh(wh)
        self._need_qty(qty)
        if isinstance(price, bool) or not isinstance(price, int) or price < 0:
            raise DepotError("INVALID_ARG")
        if self.stock(sku, wh) < qty:                        # C06, no partial shipment
            raise DepotError("INSUFFICIENT_STOCK")
        lots = self._lots_for(sku, wh)
        remaining = qty
        while remaining:                                     # C12 FIFO
            lot = lots[0]
            take = min(lot[1], remaining)
            lot[1] -= take
            remaining -= take
            if lot[1] == 0:
                lots.pop(0)
        self._cash += price * qty                            # C07
        self._update_armed(sku, wh)                          # C14

    # ----- day advance -----------------------------------------------------
    def advance_day(self):
        """C19, C13, C21, C20 in that order."""
        # 1. storage charge (C19), may take cash below 0
        units = sum(q for lots in self._lots.values() for _, q in lots)
        self._cash -= self._storage * units
        # 2. expiry (C13): lots older than shelf life are discarded
        for (sku, wh), lots in list(self._lots.items()):
            shelf = self._items[sku]["shelf"]
            if not shelf:
                continue
            expired = sum(q for d, q in lots if self._day - d > shelf)
            if expired:
                lots[:] = [[d, q] for d, q in lots if self._day - d <= shelf]
                self._events.emit("EXPIRY", sku, wh, expired)
        # 3. overdrawn check (C20): emit once on the transition below 0
        if self._cash < 0 and not self._overdrawn:
            self._events.emit("OVERDRAWN")
            self._overdrawn = True
        elif self._cash >= 0:
            self._overdrawn = False
        self._day += 1
</file>

